"""Seed MITRE ATT&CK mitigations and TTP-mitigation relationships.

Revision ID: 040_seed_mitre_mitigations
Revises: 039_notification_alerts
Create Date: 2026-03-14
"""

import base64
import json
import uuid

import sqlalchemy as sa

from alembic import op

revision = "040_seed_mitre_mitigations"
down_revision = "039_notification_alerts"
branch_labels = None
depends_on = None

# MITRE ATT&CK Enterprise mitigations (M-IDs only) + TTP relationships, base64-encoded JSON
# Source: https://github.com/mitre-attack/attack-stix-data (enterprise-attack.json)
# 44 mitigations, 1445 TTP-mitigation relationships
# fmt: off
_MITRE_B64 = ""
# fmt: on


def upgrade() -> None:
    data = json.loads(base64.b64decode(_MITRE_B64))
    mitigations = data["mitigations"]
    relationships = data["relationships"]

    conn = op.get_bind()

    mitigations_table = sa.table(
        "mitigations",
        sa.column("id", sa.dialects.postgresql.UUID),
        sa.column("mitre_id", sa.String),
        sa.column("name", sa.String),
        sa.column("description", sa.Text),
        sa.column("mitre_url", sa.Text),
        sa.column("article_count", sa.Integer),
    )

    ttp_mitigations_table = sa.table(
        "ttp_mitigations",
        sa.column("ttp_id", sa.dialects.postgresql.UUID),
        sa.column("mitigation_id", sa.dialects.postgresql.UUID),
    )

    ttps_table = sa.table(
        "ttps",
        sa.column("id", sa.dialects.postgresql.UUID),
        sa.column("technique_id", sa.String),
    )

    # Seed mitigations (skip if already exists by mitre_id)
    seeded = 0
    mid_to_uuid = {}
    for m in mitigations:
        existing = conn.execute(
            sa.select(mitigations_table.c.id).where(mitigations_table.c.mitre_id == m["mitre_id"])
        ).fetchone()
        if existing:
            mid_to_uuid[m["mitre_id"]] = existing[0]
            continue

        new_id = uuid.uuid4()
        conn.execute(
            mitigations_table.insert().values(
                id=new_id,
                mitre_id=m["mitre_id"],
                name=m["name"],
                description=m.get("description"),
                mitre_url=m.get("mitre_url"),
                article_count=0,
            )
        )
        mid_to_uuid[m["mitre_id"]] = new_id
        seeded += 1

    # Seed TTP-mitigation relationships
    links = 0
    for rel in relationships:
        mit_uuid = mid_to_uuid.get(rel["mitre_id"])
        if not mit_uuid:
            continue
        ttp_row = conn.execute(
            sa.select(ttps_table.c.id).where(ttps_table.c.technique_id == rel["technique_id"])
        ).fetchone()
        if not ttp_row:
            continue

        # Check if link already exists
        existing_link = conn.execute(
            sa.select(ttp_mitigations_table.c.ttp_id).where(
                sa.and_(
                    ttp_mitigations_table.c.ttp_id == ttp_row[0],
                    ttp_mitigations_table.c.mitigation_id == mit_uuid,
                )
            )
        ).fetchone()
        if existing_link:
            continue

        conn.execute(
            ttp_mitigations_table.insert().values(
                ttp_id=ttp_row[0],
                mitigation_id=mit_uuid,
            )
        )
        links += 1


def downgrade() -> None:
    conn = op.get_bind()
    # Remove seeded TTP-mitigation links and mitigations with article_count=0
    conn.execute(sa.text("DELETE FROM ttp_mitigations"))
    conn.execute(sa.text("DELETE FROM mitigations WHERE article_count = 0"))
